package leetcode.medium;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.IntStream;

/**
 * Created by nikoo28 on 11/2/19 6:24 PM
 */

class Tuple {

  int currentSize;
  boolean allSame;
  char firstCharacter;

  Tuple(int current, boolean allSame) {
    this.currentSize = current;
    this.allSame = allSame;
  }
}

class TicTacToe {

  private List<Tuple> rows;
  private List<Tuple> cols;
  private Tuple leftDiagonal;
  private Tuple rightDiagonal;
  private int gridSize;

  /**
   * Initialize your data structure here.
   */
  TicTacToe(int n) {

    rows = new ArrayList<>(n);
    cols = new ArrayList<>(n);

    IntStream.range(0, n).forEach(i -> {
      rows.add(new Tuple(0, false));
      cols.add(new Tuple(0, false));
    });

    leftDiagonal = new Tuple(0, false);
    rightDiagonal = new Tuple(0, false);

    gridSize = n;
  }

  /**
   * Player {player} makes a move at ({row}, {col}).
   *
   * @param row    The row of the board.
   * @param col    The column of the board.
   * @param player The player, can be either 1 or 2.
   * @return The current winning condition, can be either:
   * 0: No one wins.
   * 1: Player 1 wins.
   * 2: Player 2 wins.
   */
  int move(int row, int col, int player) {
    char playedCharacter = (player == 1) ? 'X' : 'O';

    processTuple(rows.get(row), playedCharacter);
    processTuple(cols.get(col), playedCharacter);

    if (row == col) {
      processTuple(leftDiagonal, playedCharacter);
    }

    if (row + col == gridSize - 1) {
      processTuple(rightDiagonal, playedCharacter);
    }

    return checkResult(player, gridSize);
  }

  private void processTuple(Tuple tuple, char playedCharacter) {
    tuple.currentSize++;
    if (!tuple.allSame) {
      tuple.firstCharacter = playedCharacter;
    } else {
      if (tuple.firstCharacter != playedCharacter) {
        tuple.allSame = false;
      }
    }
  }

  private int checkResult(int player, int gridSize) {
    for (Tuple tuple : rows) {
      if (tuple.currentSize == gridSize && tuple.allSame && tuple.firstCharacter == (player == 1 ? 'X' : 'O')) {
        return player;
      }
    }

    for (Tuple tuple : cols) {
      if (tuple.currentSize == gridSize && tuple.allSame && tuple.firstCharacter == (player == 1 ? 'X' : 'O')) {
        return player;
      }
    }

    if (leftDiagonal.currentSize == gridSize && leftDiagonal.allSame && leftDiagonal.firstCharacter == (player == 1 ? 'X' : 'O')) {
      return player;
    }

    if (rightDiagonal.currentSize == gridSize && rightDiagonal.allSame && rightDiagonal.firstCharacter == (player == 1 ? 'X' : 'O')) {
      return player;
    }

    if (rows.stream().filter(t -> t.currentSize == gridSize).count() > 0 || cols.stream().filter(t -> t.currentSize == gridSize).count() > 0 || (leftDiagonal.currentSize == gridSize) || (rightDiagonal.currentSize == gridSize)) {
        return 0;
    }

    return 0;
  }
}
